  /**
   * @method
   * @name backpack#fetchOpenOrder
   * @description fetch an open order by it's id
   * @see https://docs.backpack.exchange/#tag/Order/operation/get_order
   * @param {string} id order id
   * @param {string} symbol not used by fetchOpenOrder ()
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<std::any>
  fetchOpenOrder(std::any id, std::any symbol = std::any{},
                 std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchOpenOrder() requires a symbol argument"))));
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("orderId"), id},
                 };
                 std::any response = awaitValue(
                     this->privateGetApiV1Order(this->extend(request, params)));
                 return this->parseOrder(response);
               })
        .share();
  }

